import sys, os
sys.path.insert(0, os.path.dirname(__file__))
from supero.app_setup import AppSetup, PolicyDef, PolicyRule, make_seed_record, ref_link
from config import AppConfig
from schemas import ALL_SCHEMAS, PUBLIC_SCHEMAS
seed_record = make_seed_record(ALL_SCHEMAS)
POLICIES = [
    PolicyDef(role="tenant_admin", default_access="full", rules=[]),
    PolicyDef(role="tenant_user", default_access="none", rules=[
        PolicyRule(entity="provider", can_read=True),
        PolicyRule(entity="patient", can_read=True, can_create=True, can_update=True, filter_field="owner_username", filter_match="$user.name"),
        PolicyRule(entity="review", can_read=True, can_create=True, can_update=True, filter_field="owner_username", filter_match="$user.name"),
        PolicyRule(entity="metric_score", can_read=True, can_create=True, can_update=True, filter_field="owner_username", filter_match="$user.name")]),
    PolicyDef(role="viewer", default_access="none", rules=[
        PolicyRule(entity="provider", can_read=True),
        PolicyRule(entity="review", can_read=True, filter_field="provider_owner_email", filter_match="$user.name"),
        PolicyRule(entity="metric_score", can_read=True, filter_field="provider_owner_email", filter_match="$user.name")])]
SCORE_OWNERS = {}
def score(s,base,domain,review,metric,rating,note,progress):
    owner,provider=SCORE_OWNERS.get(review,("",""));slug=metric.lower().replace(" ","-").replace("&","and")
    uid=seed_record(s,base,domain,"MetricScore",{"name":review+"-"+slug,"display_name":metric,"description":note,"metric_name":metric,"rating":rating,"justification":note,"review_uuid":review,"owner_username":owner,"provider_owner_email":provider},progress=progress,tenant_name="default-tenant")
    if uid and review: ref_link(s,base,domain,ALL_SCHEMAS,"MetricScore",uid,"Review",review)
    return uid
def link_review(s,base,domain,review,patient,provider):
    if review and patient: ref_link(s,base,domain,ALL_SCHEMAS,"Review",review,"Patient",patient)
    if review and provider: ref_link(s,base,domain,ALL_SCHEMAS,"Review",review,"Provider",provider)
